def is_latin_square(matrix):
    n = len(matrix)
    # Check rows
    for row in matrix:
        if len(set(row)) != n:
            return False
    # Check cols
    for j in range(n):
        col = [matrix[i][j] for i in range(n)]
        if len(set(col)) != n:
            return False
    return True

