    # The problem says "any diagonal whose number of entries is a multiple of three"
    # This includes any sub-segment of a diagonal.
    # If any 3 consecutive entries on a diagonal must be a permutation of {0,1,2},
    # that's the strongest condition.

    # Check all 3-length diagonals
    for i in range(n):
        for j in range(n):
            # Direction (1, 1)
            if i + 2 < n and j + 2 < n:
                diag = [grid[i][j], grid[i+1][j+1], grid[i+2][j+2]]
                if sorted(diag) != [0, 1, 2]:
                    return False
            # Direction (1, -1)
            if i + 2 < n and j - 2 >= 0:
                diag = [grid[i][j], grid[i+1][j-1], grid[i+2][j-2]]
                if sorted(diag) != [0, 1, 2]:
                    return False
    return True

